Dynamic Programming SolutionThe above recursive solution has exponential time complexity in the worst case. Please note that we make two recursive calls in the last if condition. We can clearly notice overlapping subproblems here as we make calls for (n-1, m-1), (n, m-2) and/or (n-1, m). So we can use Dynamic Programming to solve this problem.Create a boolean 2D dp array of size (n + 1) * (m + 1).  Please note that the range of values in the recursion goes from 0 to text length (or n) and 0 to pattern length (or m)dp[i][j] is going to be true if first i characters of text match with first j characters of pattern.If both strings are empty, then it’s a match, thus, dp[0][0] = true.For other cases, we simply follow the above recursive solution.
            C++

    #include <iostream>
#include <vector>
using namespace std;

bool isMatch(string t, string p) {
    int n = t.size();
    int m = p.size();

    // DP table where dp[i][j] means whether first i characters in t
    // match the first j characters in p
    vector<vector<bool>> dp(n + 1, vector<bool>(m + 1, false));

    // Empty pattern matches empty text
    dp[0][0] = true;

    // Deals with patterns like a*, a*b*, a*b*c* etc, where '*' 
    // can eliminate preceding character
    for (int j = 1; j <= m; ++j) {
        if (p[j - 1] == '*' && j > 1) {
            dp[0][j] = dp[0][j - 2];
        }
    }

    // Fill the table
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {

            // Characters match
            if (p[j - 1] == '.' || t[i - 1] == p[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1]; 
            } 

            else if (p[j - 1] == '*' && j > 1) {

                // Two cases:
                // 1. '*' represents zero occurrence of the preceding character
                // 2. '*' represents one or more occurrence of the preceding character
                dp[i][j] = dp[i][j - 2] || 
                           (dp[i - 1][j] && (p[j - 2] == t[i - 1] || p[j - 2] == '.'));
            }
        }
    }

    return dp[n][m];
}

int main() {
    cout << boolalpha << isMatch("aab", "a.*") << endl; 
    cout << boolalpha << isMatch("aa", "a") << endl; 
    cout << boolalpha << isMatch("aa", "a*") << endl; 
    cout << boolalpha << isMatch("ab", ".*") << endl;  
    cout << boolalpha << isMatch("mississippi", "mis*is*p*.") << endl; 
    return 0;
}


